# Generates UAT.csv (UTF-8 with BOM so Excel opens Greek correctly). Run: python3 scripts/build-uat.py
import csv
H = ["ID","Ενότητα","Περιγραφή","Συσκευή / Περιβάλλον","Βήματα","Αναμενόμενο αποτέλεσμα","Αποτέλεσμα (Pass/Fail)","Severity","Σχετικό εύρημα (REPORT.md)","Σχόλια δοκιμαστή"]
R = []
def r(id_, sec, desc, env, steps, exp, sev, ref=""):
    R.append([id_, sec, desc, env, " | ".join(f"{i+1}) {s}" for i, s in enumerate(steps)), exp, "Pending", sev, ref, ""])

